99			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
100			Expiry: "2026-10-01", Method: "m", Error: 0.1, Summary: "s",
101		})
102		if err != nil {
103			t.Fatalf("add cert: %v", err)
104		}
105		cert.Expiry = "2030-01-01"
106	
107		d, err := l.CanUse("M-1")
108		if err != nil {
109			t.Fatalf("can use: %v", err)
110		}
111		if d.Allowed {
112			t.Fatal("正式证书已到期，改写返回结果的截止日不应恢复使用资格")
113		}
114		if !containsReason(d.Reasons, "到期") {
115			t.Fatalf("拒绝原因应包含到期，得到 %v", d.Reasons)
116		}
117	}
118	
119	// TestDuplicateReturnedCertificateIsIndependentCopy 验证同号同内容再次提交
120	// 返回的已有证书同样是独立副本：两份返回结果互不影响，也不影响正式证书；
121	// 按原始内容再次提交仍标记为重复并返回原业务内容与最初录入时间。
122	func TestDuplicateReturnedCertificateIsIndependentCopy(t *testing.T) {
123		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
124		l := newTestLedger(t, clock)
125		mustRegister(t, l, "M-1", "万用表", 0.5)
126	
127		in := CertificateInput{
128			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
129			Expiry: "2027-09-01", Method: "m", Error: 0.2, Summary: "s",
130		}
131		first, dup, err := l.AddCertificate(in)
132		if err != nil || dup {
133			t.Fatalf("首次录入应成功且非重复，err=%v dup=%v", err, dup)
134		}
135		second, dup, err := l.AddCertificate(in)
136		if err != nil || !dup {
137			t.Fatalf("同号同内容再次提交应标记为重复，err=%v dup=%v", err, dup)
138		}
139	
140		// 两份返回结果各自独立：整理第一份不影响第二份，也不影响正式证书。
141		first.Error = 0.9
142		first.Summary = "第一份自己整理的内容"
143		if second.Error != 0.2 || second.Summary != "s" {
144			t.Fatalf("整理第一份返回结果影响了第二份：%+v", second)
145		}
146		if got := l.LatestCertificate("M-1"); got == nil || got.Error != 0.2 {
147			t.Fatalf("整理返回结果改写了正式证书：%+v", got)
148		}
149	
150		// 整理第二份也不影响此前已取得的最近证书与核对结果。
151		latest := l.LatestCertificate("M-1")
152		review, _ := l.Review("M-1")
153		second.Number = "C-伪造"
154		second.InstrumentID = "M-9"
155		if latest.Number != "C-1" || review.Latest.Number != "C-1" {
156			t.Fatal("整理重复返回结果影响了此前已取得的最近证书或核对结果")
157		}
158	
159		// 按原始内容再次提交仍标记为重复，返回原业务内容和最初录入时间，
160		// 历史中只保留一张。
161		clock.t = mustDate(t, "2026-10-03")
162		third, dup, err := l.AddCertificate(in)
163		if err != nil || !dup {
164			t.Fatalf("整理过返回数据后按原始内容提交仍应标记为重复，err=%v dup=%v", err, dup)
165		}
166		if third.Error != 0.2 || third.Summary != "s" || third.CreatedAt != first.CreatedAt {
167			t.Fatalf("重复提交应返回原业务内容与最初录入时间：%+v", third)
168		}
169		if n := len(l.data.Certificates); n != 1 {
170			t.Fatalf("历史中应只保留一张证书，得到 %d 张", n)
171		}
172	
173		// 同号但内容不同仍报冲突，不因此前整理过返回数据而接受覆盖。
174		different := in
175		different.Error = 0.1
176		if _, _, err := l.AddCertificate(different); !IsConflict(err) {
177			t.Fatalf("同号不同内容仍应报冲突，得到 %v", err)
178		}
179	}
