// 同一次核对的各部分必须共用同一个 today，避免跨午夜时判断不一致。
func decideUsage(inst *Instrument, latest *Certificate, today time.Time) *UsageDecision {
	d := &UsageDecision{InstrumentID: inst.ID, evaluatedAt: today}
